-- Seed: brands, categories and products from the current tayscientific.com.my product page.
-- Run AFTER migration_brand_page.sql. Safe to re-run. SKUs are placeholders: replace with real part numbers.

-- 1) Remove the starter demo data
delete from products where sku like 'DEMO-%';
delete from brands where slug like 'sample-brand-%';
delete from categories where slug in ('analytical-instruments','microscopes-imaging','balances-weighing','centrifuges-mixers','glassware-plasticware','chemicals-reagents') and not exists (select 1 from products where category_id = categories.id);

